    h, w = len(grid), len(grid[0])
    # A full contrasting row/column is the guide; mark the far edge of the
    # colored shape on the same side of that guide with a parallel line.
    guide = None
    for r in range(h):
        if len(set(grid[r])) == 1 and len(set(x for row in grid for x in row)) > 1:
            guide = ("row", r, grid[r][0])
            break
    if guide is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and len(set(x for row in grid for x in row)) > 1:
                guide = ("col", c, vals[0])
                break
    if guide is None:
        return [row[:] for row in grid]
    axis, pos, guide_color = guide
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (grid[0][0], guide_color)]
    if not cells:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    if axis == "row":
        above = [r for r, c in cells if r < pos]
        below = [r for r, c in cells if r > pos]
        if below:
            target = max(r for r, c in cells if r > pos) + 1
        elif above:
            target = min(r for r, c in cells if r < pos) - 1
        else:
            return out
        if 0 <= target < h:
            out[target] = [8] * w
    else:
        left = [c for r, c in cells if c < pos]
        right = [c for r, c in cells if c > pos]
        if right:
            target = max(c for r, c in cells if c > pos) + 1
        elif left:
            target = min(c for r, c in cells if c < pos) - 1
        else:
            return out
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    return out

